gdr.ValidationScript:
// eslint-disable-next-line @typescript-eslint/no-unused-vars
function isReviewNeeded() {
    // If vendor has proposed discount rate, proposal need to be validate by AP
    return !!Data.GetValue("ProposedDiscountRate__");
}
function Run() {
    if (Data.GetValue("State") < 50) {
        return;
    }
    const currentName = Data.GetActionName();
    const currentAction = Data.GetActionType();
    Log.Info(`Action: ${currentAction ? currentAction : "<empty>"}, Name: ${currentName ? currentName : "<empty>"}, Device: ${Data.GetActionDevice()}`);
    const requestedDiscountLimitDate = Data.GetValue("RequestedPaymentDate__");
    const requestedDiscountRate = Data.GetValue("ProposedDiscountRate__");
    Log.Info(`About to send Early payment proposal with discount limit date to ${requestedDiscountLimitDate}`);
    if (requestedDiscountRate) {
        Log.Info(`Option 'Vendor can propose discount rate' enabled with discount rate requested of ${requestedDiscountRate} %`);
    }
    switch (currentName) {
        case "Approve":
            InvoiceUpdateHelper.UpdateInvoicesWithDiscountInfo(false);
            break;
        default:
            if (isReviewNeeded()) {
                Log.Info("Proposal need to be reviewed. Send to approver");
                Process.PreventApproval();
                InvoiceUpdateHelper.UpdateInvoicesWithDiscountInfo(true);
                NotificationHelper.SendEmail("EarlyPaymentsProposals_NotifNextApprover_XX.htm", Lib.AP.VendorPortal.GetDefaultApUserLogin());
            }
            else {
                Log.Info("Proposal doesn't need to be reviewed. Approve it automatically.");
                InvoiceUpdateHelper.UpdateInvoicesWithDiscountInfo(false);
            }
            break;
    }
}
var InvoiceUpdateHelper;
(function (InvoiceUpdateHelper) {
    function updateDiscountValuesOnCI(discountInfo, pendingReview) {
        Log.Verbose(`Updating CI ${discountInfo.CIRuidEx} : update discount request infos`);
        const valuesToUpdateOnCI = {
            DiscountExpirationDate__: discountInfo.DiscountExpirationDate,
            DiscountAmount__: discountInfo.DiscountAmount,
            DiscountRate__: discountInfo.DiscountRate,
            DiscountState__: discountInfo.DiscountState
        };
        if (!pendingReview) {
            Log.Verbose(`Updating CI ${discountInfo.CIRuidEx} : update accepted discount infos`);
            valuesToUpdateOnCI.DiscountLimitDate__ = discountInfo.DiscountExpirationDate;
            valuesToUpdateOnCI.DiscountPercent__ = discountInfo.DiscountRate;
            valuesToUpdateOnCI.EstimatedDiscountAmount__ = discountInfo.DiscountAmount;
            valuesToUpdateOnCI.InvoiceAmountWithDiscount__ = discountInfo.InvoiceAmountWithDiscount;
        }
        Log.Verbose(`Updating CI ${discountInfo.CIRuidEx} (Discount state : ${discountInfo.DiscountState})`);
        return Process.UpdateProcessInstanceDataAsync(discountInfo.CIRuidEx, JSON.stringify({ fields: valuesToUpdateOnCI }));
    }
    function UpdateInvoicesWithDiscountInfo(pendingReview) {
        let allInSuccess = true;
        const discountExpirationDate = Data.GetValue("RequestedPaymentDate__");
        const table = Data.GetTable("Invoices__");
        const nbInvoices = table.GetItemCount();
        const vipsToUpdate = new Map();
        for (let i = 0; i < nbInvoices; i++) {
            const invoice = table.GetItem(i);
            const discountAmount = invoice.GetValue("ProposedInvoiceDiscountAmount__");
            const dueDate = invoice.GetValue("DueDate__");
            const isSelected = invoice.GetValue("IsSelected__");
            const VIPRuidEx = invoice.GetValue("RUIDEx__");
            let discountState = Lib.AP.CIDiscountState.Refused;
            if (pendingReview) {
                discountState = Lib.AP.CIDiscountState.PendingReview;
            }
            else if (isSelected) {
                discountState = Lib.AP.CIDiscountState.Accepted;
            }
            if (Sys.Helpers.Date.CompareDate(dueDate, discountExpirationDate) === 1) {
                const discountInfo = {
                    IsSelected: isSelected,
                    CIRuidEx: invoice.GetValue("PortalRuidEx__"),
                    VIPRuidEx: VIPRuidEx,
                    DiscountAmount: discountAmount,
                    InvoiceAmountWithDiscount: invoice.GetValue("ProposedInvoiceAmountWithDiscount__"),
                    DiscountRate: invoice.GetValue("ProposedInvoiceDiscountRate__"),
                    DiscountExpirationDate: discountExpirationDate,
                    DiscountState: discountState
                };
                const CIUpdateResult = updateDiscountValuesOnCI(discountInfo, pendingReview);
                if (CIUpdateResult && !pendingReview && isSelected) {
                    Log.Verbose(`Add VIP ${discountInfo.VIPRuidEx} in list of VIP to update`);
                    vipsToUpdate.set(discountInfo.VIPRuidEx, discountInfo);
                }
                allInSuccess = CIUpdateResult && allInSuccess;
            }
            else {
                Log.Warn(`Discount not proposed : VIP ${VIPRuidEx} with due date expired - ${Sys.Helpers.Date.Date2DBDate(dueDate)}`);
            }
        }
        // now update VIPS if needed
        if (vipsToUpdate.size > 0) {
            Log.Verbose(`Update discount info on ${vipsToUpdate.size} VIPs`);
            allInSuccess = Lib.AP.VendorPortal.ScheduledProposeEarlyPaymentOnVIP(vipsToUpdate, Variable.GetValueAsString("shortLogin")) &&
                allInSuccess;
        }
        if (!allInSuccess) {
            Log.Warn("Some Customer invoice/Vendor invoice have not been updated successfully with discount info");
        }
        return allInSuccess;
    }
    InvoiceUpdateHelper.UpdateInvoicesWithDiscountInfo = UpdateInvoicesWithDiscountInfo;
})(InvoiceUpdateHelper || (InvoiceUpdateHelper = {}));
var NotificationHelper;
(function (NotificationHelper) {
    function SendEmail(template, receiverLogin) {
        const customTags = {};
        const emailReceiver = Users.GetUserAsProcessAdmin(receiverLogin);
        let destLanguage;
        if (emailReceiver) {
            destLanguage = emailReceiver.GetValue("Language");
            customTags.ProcessUrl = emailReceiver.GetProcessURL(Data.GetValue("Ruidex"), true);
        }
        else {
            Log.Error(`Cannot retrieve user with value '${receiverLogin}'`);
            return;
        }
        const destEmail = emailReceiver.GetValue("EmailAddress");
        const email = Sys.EmailNotification.CreateEmailWithUser(emailReceiver, destEmail, null, template, customTags, true);
        if (email) {
            Sys.EmailNotification.AddSender(email, "notification@eskerondemand.com", Language.TranslateInto("Esker Accounts payable", destLanguage, false));
            Sys.EmailNotification.SendEmail(email);
        }
        else {
            Log.Error(`Cannot send email to '${destEmail}'`);
        }
    }
    NotificationHelper.SendEmail = SendEmail;
})(NotificationHelper || (NotificationHelper = {}));
Run();
//# sourceMappingURL=validationscript.js.map

gdr.ExtractionScript:
// eslint-disable-next-line @typescript-eslint/no-unused-vars
var extractionscript;
(function (extractionscript) {
    function Run() {
        InvoiceLoadingHelper.Load();
        ForwardToAP();
    }
    function ForwardToAP() {
        const apUserLogin = Lib.AP.VendorPortal.GetDefaultApUserLogin();
        if (!apUserLogin) {
            Log.Error("Cannot retrieve default AP clerk");
            return;
        }
        Log.Info("Forwarding to " + apUserLogin);
        Process.Forward(apUserLogin);
    }
    let InvoiceLoadingHelper;
    (function (InvoiceLoadingHelper) {
        let discountInfos = {};
        function parseDiscountInfosFromPreviousProcess() {
            const discountInfosAsString = Variable.GetValueAsString("InvoicesDiscountInfo");
            try {
                const discountInfosAsJSON = JSON.parse(discountInfosAsString);
                discountInfos = Sys.Helpers.Array.Reduce(discountInfosAsJSON, (acc, item) => {
                    acc[item.RUIDEX__] = item;
                    return acc;
                }, {});
            }
            catch (exception) {
                Log.Error(`Could not parse variable InvoicesDiscountInfo as JSON: ${exception}`);
            }
        }
        function fillHeaderFields(firstInvoice) {
            const headerFields = [
                "CompanyCode__",
                "VendorNumber__",
                "VendorName__"
            ];
            for (const field of headerFields) {
                Data.SetValue(field, firstInvoice[field]);
            }
        }
        function getInvoiceList() {
            const ancestorRuids = Variable.GetValueAsString("AncestorsRuid");
            if (ancestorRuids) {
                return ancestorRuids.split("|");
            }
            return [];
        }
        function buildLDAPFilter(ruidExList) {
            const filters = [];
            for (const ruidex of ruidExList) {
                filters.push(Sys.Helpers.LdapUtil.FilterEqual("PortalRuidEx__", ruidex));
            }
            return Sys.Helpers.LdapUtil.FilterOr(...filters).toString();
        }
        function addLine(item, result) {
            // Consolidate query result with discount infos from previous process (Early payment request)
            if (result.PortalRuidEx__) {
                const discountInfo = discountInfos[result.PortalRuidEx__];
                if (discountInfo) {
                    result.ProposedInvoiceDiscountRate__ = discountInfo.Discount_rate__;
                    result.ProposedInvoiceDiscountAmount__ = discountInfo.Discount_amount__;
                    result.ProposedInvoiceAmountWithDiscount__ = discountInfo.InvoiceAmountWithDiscount__;
                    result.PaymentTermDayLimit__ = discountInfo.PaymentTermDayLimit__;
                    result.Remaining__ = discountInfo.Remaining__;
                }
            }
            for (const attribute in result) {
                if (Object.prototype.hasOwnProperty.call(result, attribute)) {
                    const fieldName = attribute === "RUIDEx" ? "RUIDEx__" : attribute;
                    item.SetValue(fieldName, result[attribute]);
                }
            }
            // Each item is selected by default
            item.SetValue("IsSelected__", true);
        }
        function Load() {
            const ruidExList = getInvoiceList();
            if (!ruidExList || ruidExList.length <= 0) {
                return;
            }
            parseDiscountInfosFromPreviousProcess();
            const filter = buildLDAPFilter(ruidExList);
            const fields = [
                "RUIDEx",
                "CompanyCode__",
                "VendorNumber__",
                "VendorName__",
                "PortalRuidEx__",
                "DueDate__",
                "InvoiceAmount__",
                "InvoiceCurrency__",
                "InvoiceDate__",
                "InvoiceNumber__",
                "OrderNumber__",
                "PostingDate__"
            ];
            Sys.GenericAPI.PromisedQuery({
                table: "CDNAME#Vendor invoice",
                filter: filter,
                attributes: fields,
                maxRecords: 500,
                additionalOptions: {
                    useConstantQueryCache: true,
                    asAdmin: true,
                    searchInArchive: false
                }
            })
                .Then(function (results) {
                if (!results || !results.length) {
                    Log.Error(`addInvoice - Invoice not found with filter ${filter}`);
                }
                else {
                    // Fill hearder fields (from the first invoice)
                    fillHeaderFields(results[0]);
                    // Fill table
                    for (const result of results) {
                        const newItem = Data.GetTable("Invoices__").AddItem(true);
                        if (newItem) {
                            addLine(newItem, result);
                        }
                    }
                }
            })
                .Catch(function (error) {
                Log.Error(`addInvoice - Error when retrieving invoice: ${error}`);
            });
        }
        InvoiceLoadingHelper.Load = Load;
    })(InvoiceLoadingHelper || (InvoiceLoadingHelper = {}));
    Run();
})(extractionscript || (extractionscript = {}));
//# sourceMappingURL=extractionscript.js.map

ui.CustomScript:
function getCurrency() {
    const firstItem = Controls.Invoices__.GetItem(0);
    if (firstItem) {
        return firstItem.GetValue("InvoiceCurrency__");
    }
    return "";
}
var SummaryHelper;
(function (SummaryHelper) {
    function AddSelectedItem(label, amount, showCurrency = false) {
        const item = Controls.SummarySelected__.AddItem(false);
        item.SetValue("Labels__", Language.Translate(label, true));
        if (amount !== undefined) {
            item.SetValue("Amount__", `${amount} ${showCurrency ? getCurrency() : ""}`);
        }
    }
    function Refresh() {
        let selectedInvoicesCount = 0;
        let totalInvoicesAmount = 0;
        let totalInvoicesAmountMinusFee = 0;
        for (let i = 0; i < Controls.Invoices__.GetItemCount(); i++) {
            const item = Controls.Invoices__.GetItem(i);
            if (item.GetValue("IsSelected__")) {
                selectedInvoicesCount += 1;
                totalInvoicesAmount += item.GetValue("InvoiceAmount__");
                totalInvoicesAmountMinusFee += item.GetValue("ProposedInvoiceAmountWithDiscount__");
            }
        }
        let totalFees = totalInvoicesAmount - totalInvoicesAmountMinusFee;
        const currencyPrecision = Lib.P2P.Currency.Get(getCurrency());
        totalInvoicesAmount = Sys.Helpers.Round(totalInvoicesAmount, currencyPrecision.amountPrecision);
        totalInvoicesAmountMinusFee = Sys.Helpers.Round(totalInvoicesAmountMinusFee, currencyPrecision.amountPrecision);
        totalFees = Sys.Helpers.Round(totalFees, currencyPrecision.amountPrecision);
        Controls.SummarySelected__.SetItemCount(0);
        AddSelectedItem("_Summary selected invoices", selectedInvoicesCount);
        Controls.SummarySelected__.GetRow(0).AddStyle("highlight-info");
        AddSelectedItem("_Summary selected invoices amount", totalInvoicesAmount, true);
        AddSelectedItem("_Summary selected discount amount", totalFees, true);
        AddSelectedItem("_Summary selected payment amount", totalInvoicesAmountMinusFee, true);
        Controls.SummarySelected__.GetRow(3).AddStyle("highlight-success");
        refreshSubmitButtonLabel(selectedInvoicesCount);
    }
    SummaryHelper.Refresh = Refresh;
    function refreshSubmitButtonLabel(selectedInvoicesCount) {
        if (selectedInvoicesCount === Controls.Invoices__.GetItemCount()) {
            // Accept all
            Controls.SubmitButton__.SetButtonLabel("_Accept proposal");
        }
        else if (selectedInvoicesCount === 0) {
            // Reject all
            Controls.SubmitButton__.SetButtonLabel("_Refuse proposal");
        }
        else {
            // Accept some
            Controls.SubmitButton__.SetButtonLabel("_Accept part of the proposal");
        }
    }
    function Setup() {
        Controls.Recap__.SetText("");
        Controls.Recap__.Hide(true);
        Controls.SummarySelected__.SetWidth("auto");
        Refresh();
    }
    SummaryHelper.Setup = Setup;
})(SummaryHelper || (SummaryHelper = {}));
var TableHelper;
(function (TableHelper) {
    function Refresh() {
        for (let i = 0; i < Controls.Invoices__.GetLineCount(); i++) {
            const row = Controls.Invoices__.GetRow(i);
            const item = row.GetItem();
            if (!item) {
                // GetLineCount does not represent the number of items currently visible,
                // but the maximum possible number of items that can be displayed at any time.
                // If item does not exist, break loop
                break;
            }
            // Check / uncheck row according to checkbox
            const isSelected = item.GetValue("IsSelected__");
            row.SetSelected(isSelected);
            if (row.GetSelected()) {
                row.RemoveStyle("highlight-grayed");
            }
            else {
                row.AddStyle("highlight-grayed");
            }
        }
    }
    TableHelper.Refresh = Refresh;
})(TableHelper || (TableHelper = {}));
function setupEvents() {
    Controls.Invoices__.OnSelectLine = function (lineIndex) {
        // Check/Uncheck the header's checkbox does not trigger OnSelectAllLines/OnUnselectAllLines event
        // so we have to infer the event type with the state of the first row
        if (lineIndex === -1) {
            const firstRow = Controls.Invoices__.GetRow(0);
            if (!firstRow) {
                return;
            }
            for (let i = 0; i < Controls.Invoices__.GetItemCount(); i++) {
                const item = Controls.Invoices__.GetItem(i);
                const isSelected = firstRow.GetSelected();
                item.SetValue("IsSelected__", isSelected);
            }
        }
        else {
            const row = Controls.Invoices__.GetRow(lineIndex - 1);
            const isSelected = row.GetSelected();
            row.GetItem().SetValue("IsSelected__", isSelected);
        }
        SummaryHelper.Refresh();
        TableHelper.Refresh();
    };
    Controls.Invoices__.OnRefreshRow = function () {
        TableHelper.Refresh();
    };
    Controls.SubmitButton__.OnClick = function () {
        ProcessInstance.Approve("Approve");
    };
    Controls.Invoices__.ActionViewPDF__.OnClick = function () {
        const invoiceRUIDEX = this.GetRow().RUIDEx__.GetValue();
        const url = Sys.Helpers.GetAttachFileURL(invoiceRUIDEX, 0, -2);
        Process.OpenLink(url);
    };
}
function setupHeaderFields() {
    // Set banner based on current status
    const htmlTitle = `<div style='color: #435464;margin: 0px -10px 0px -10px;line-height: 2em;text-align: center; font-family: Arial, Helvetica, sans-serif'>
	<span style='font-size: 20pt;font-weight: bold'>${Language.Translate("Early payment proposal")}</span>
</div>`;
    Controls.HTMLBanner__.SetHTML(htmlTitle);
    const submitDateTime = Data.GetValue("SubmitDateTime");
    if (submitDateTime) {
        Controls.CreationDateTime__.SetValue(submitDateTime.toLocaleString(User.culture));
    }
    const requestedPaymentDate = Data.GetValue("RequestedPaymentDate__");
    if (requestedPaymentDate) {
        Controls.RequestedPaymentDate_Header__.SetText(requestedPaymentDate.toLocaleDateString(User.culture));
    }
    if (Data.GetValue("State") != 70 || ProcessInstance.isReadOnly) {
        Controls.SubmitButton__.Hide(true);
        Controls.Invoices__.IsSelected__.Hide(false);
    }
}
function Main() {
    setupEvents();
    setupHeaderFields();
    SummaryHelper.Setup();
    TableHelper.Refresh();
}
Main();
//# sourceMappingURL=customscript.js.map

